const navItems: NavItem[] = [
  { label: "Dashboard", href: "/", icon: <DashboardIcon /> },
  { label: "MyBots", href: "/my-bots", icon: <MyBotsIcon /> },
  { label: "Create Bot", href: "/create-bot", icon: <CreateBotIcon />, hasIndicator: true },
  { label: "Settings", href: "/settings", icon: <SettingsIcon /> },
  { label: "Usage Stats", href: "/usage-stats", icon: <UsageStatsIcon /> },
  { label: "Chat History", href: "/chat-history", icon: <ChatHistoryIcon /> },
];

function Sidebar({ onClose }: { onClose?: () => void }) {
  const location = useLocation();

  return (
    <div className="flex flex-col justify-between h-full py-4 px-4">
      <div className="flex flex-col gap-12">
        {/* Logo */}
        <div className="flex items-center justify-between px-2 pt-2">
          <span className="font-poppins font-semibold text-[24px] text-[#1E2875] tracking-[0.25px]">
            VectorDesk
          </span>
          {onClose && (
            <button onClick={onClose} className="lg:hidden p-1">
              <CloseIcon />
            </button>
          )}
        </div>

        {/* Nav Items */}
        <nav className="flex flex-col gap-2.5">
          {navItems.map((item) => {
            const isActive = location.pathname === item.href;
            return (
              <Link
                key={item.href}
                to={item.href}
                onClick={onClose}
                className={`flex items-center gap-[7.5px] px-[7.5px] py-[7.5px] rounded-[6px] transition-colors ${
                  isActive
                    ? "bg-[rgba(30,40,117,0.11)]"
                    : "hover:bg-[rgba(30,40,117,0.06)]"
                }`}
              >
                {item.icon}
                <span
                  className={`font-poppins text-[17px] tracking-[0.25px] flex-1 ${
                    item.hasIndicator ? "font-semibold" : "font-medium"
                  } text-[#373B5C]`}
                >
                  {item.label}
                </span>
                {item.hasIndicator && (
                  <svg width="5" height="5" viewBox="0 0 5 5" fill="none">
                    <circle cx="2.5" cy="2.5" r="2.5" fill="#082567"/>
                  </svg>
                )}
              </Link>
            );
          })}
        </nav>
      </div>

      {/* Bottom section */}
      <div className="flex flex-col gap-8">
        {/* PRO Upgrade Card */}
        <div className="flex flex-col items-center gap-3 rounded-[16px] bg-[#F2F6FA] pt-6 px-2 overflow-hidden">
          <p className="self-stretch font-poppins text-[#5B5E6F] text-[20px] leading-tight tracking-[0.25px]">
            Upgrade to{" "}
            <span className="font-bold">PRO Account</span>
          </p>
          <div className="flex gap-3 self-stretch pb-4">
            <div className="flex-1">
              <p className="font-poppins text-[13px] text-[#9294A0] leading-snug tracking-[0.25px]">
                Start your PRO subscription today for only{" "}
                <span className="font-bold">$35/month</span>
              </p>
            </div>
            <img
              src="https://api.builder.io/api/v1/image/assets/TEMP/5f00ecf83784a1f9ee0ff6377cb66253af434c03?width=212"
              alt="PRO upgrade"
              className="w-[80px] h-[140px] object-contain flex-shrink-0"
            />
          </div>
        </div>

        {/* Logout */}
        <button className="flex items-center gap-[7.5px] px-[7.5px] py-[7.5px] rounded-[6px] hover:bg-[rgba(30,40,117,0.06)] transition-colors w-full">
          <span className="font-poppins font-medium text-[17px] text-[#373B5C] flex-1 text-left tracking-[0.25px]">
            Logout
          </span>
          <LogoutIcon />
        </button>
      </div>
    </div>
  );
}

