interface LayoutProps {
  children: React.ReactNode;
}

export default function Layout({ children }: LayoutProps) {
  const [sidebarOpen, setSidebarOpen] = useState(false);

  return (
    <div className="min-h-screen bg-[#F2F6FA]">
      {/* Mobile overlay */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 bg-black/30 z-40 lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Mobile sidebar drawer */}
      <div
        className={`fixed left-0 top-0 h-full w-[240px] z-50 lg:hidden transition-transform duration-300 ${
          sidebarOpen ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        <div className="h-full rounded-r-[16px] bg-white/80 backdrop-blur-sm shadow-sidebar overflow-y-auto">
          <Sidebar onClose={() => setSidebarOpen(false)} />
        </div>
      </div>

      <div className="flex min-h-screen p-4 lg:p-8 gap-6">
        {/* Desktop sidebar */}
        <aside className="hidden lg:flex flex-col w-[240px] flex-shrink-0">
          <div className="rounded-[16px] bg-white/50 shadow-sidebar h-full max-h-[960px] sticky top-8">
            <Sidebar />
          </div>
        </aside>

        {/* Main content */}
        <main className="flex-1 min-w-0 flex flex-col gap-6">
          {/* Top bar */}
          <div className="flex items-center justify-between">
            <button
              className="lg:hidden p-2 rounded-lg hover:bg-white/50 transition-colors"
              onClick={() => setSidebarOpen(true)}
            >
              <HamburgerIcon />
            </button>
            <div className="ml-auto">
              <TopBar />
            </div>
          </div>

          {/* Page content */}
          {children}
        </main>
      </div>
    </div>
  );
}
